-- Real photographs for the demo farm: one photo per animal, never shared between two animals.
-- 77 animals get a photo from Unsplash or Pexels (taken in Bangladesh, credited, linked to its page).
-- The rest show "No photo yet", as on a real farm. Generated by scripts/demo/assign-real-photos.mts.
DELETE FROM "animal_media" m
USING "animals" a JOIN "farms" f ON f.id = a.farm_id AND f.name LIKE '%(demo)'
WHERE m.animal_id = a.id AND m.url LIKE 'https://images.unsplash.com/%' AND m.credit LIKE '%· Unsplash ·%';
--> statement-breakpoint
